new_update='''    private void updatePlayer() {\n        if (phaseTitle == null || phases.isEmpty()) return;\n        Phase p = phases.get(phaseIndex);\n        boolean phaseChanged = renderedPhaseIndex != phaseIndex;\n        if (phaseChanged) {\n            renderedPhaseIndex = phaseIndex;\n            phaseTitle.setText(p.title);\n            phaseCounter.setText((phaseIndex + 1) + " / " + phases.size());\n            sayText.setText(p.say == null || p.say.trim().isEmpty() ? "—" : p.say);\n            doText.setText(p.action == null || p.action.trim().isEmpty() ? "—" : p.action);\n            rainStrip.setVisibility(p.type == Phase.RAIN ? View.VISIBLE : View.GONE);\n            oceanStrip.setVisibility(p.type == Phase.OCEAN ? View.VISIBLE : View.GONE);\n            resetSmartReading();\n            if (textScroll != null) textScroll.post(() -> textScroll.scrollTo(0, 0));\n        }\n\n        globalTimer.setText(format(globalElapsedMs));\n        if (phaseElapsedDisplay != null) phaseElapsedDisplay.setText(format(phaseElapsedMs));\n        long planned = p.minutes * 60000L;\n        long remaining = planned - phaseElapsedMs;\n        if (remaining >= 0) {\n            phaseRemainingCaption.setText("RESTANT");\n            phaseRemainingCaption.setTextColor(MUTED);\n            phaseTimer.setText(format(remaining));\n            phaseTimer.setTextColor(CLAYER());\n        } else {\n            phaseRemainingCaption.setText("DÉPASSÉ");\n            phaseRemainingCaption.setTextColor(MAUVE);\n            phaseTimer.setText("+" + format(-remaining));\n            phaseTimer.setTextColor(MAUVE);\n        }\n\n        String next = phaseIndex + 1 < phases.size() ? "Ensuite : " + phases.get(phaseIndex + 1).title : "Dernier temps";\n        if (autoPhaseReadyAt > 0L && phaseIndex + 1 < phases.size()) {\n            long left = Math.max(0L, autoPhaseReadyAt - SystemClock.elapsedRealtime());\n            nextLabel.setText("Passage automatique dans " + Math.max(1L, (left + 999L) / 1000L) + " s  •  " + next);\n        } else nextLabel.setText(next);\n\n        int totalPlanned = plannedTotalMinutes() * 60000;\n        globalProgress.setMax(Math.max(1, totalPlanned));\n        globalProgress.setProgress((int) Math.min(globalElapsedMs, totalPlanned));\n        phaseProgress.setMax(Math.max(1, p.minutes * 60000));\n        phaseProgress.setProgress((int) Math.min(phaseElapsedMs, p.minutes * 60000L));\n\n        inhaleValue.setText(inhaleSeconds + "s");\n        exhaleValue.setText(exhaleSeconds + "s");\n        waveValue.setText(waveSeconds + " s");\n        if (p.type == Phase.RAIN) updateRain();\n        if (p.type == Phase.OCEAN) updateWave();\n        if (musicVolumeValue != null) musicVolumeValue.setText(musicVolume + "%");\n    }\n\n    private int plannedTotalMinutes'''
