new_ticker='''    private int readingWordsPerMinute() {\n        return 45 + (int) Math.round((Math.max(1, autoSpeed) - 1) * (115.0 / 99.0));\n    }\n\n    private void updateAutoStatus() {\n        if (autoScrollStatus != null) autoScrollStatus.setText(autoScroll ? readingWordsPerMinute() + " mots/min" : "OFF");\n        if (autoScrollButton != null) autoScrollButton.setText(autoScroll ? "AUTO ✓" : "AUTO");\n        if (autoPhaseButton != null) autoPhaseButton.setText(autoPhase ? "PHASES AUTO ✓" : "PHASES AUTO");\n    }\n\n    private String currentReadingText() {\n        if (phases.isEmpty() || phaseIndex < 0 || phaseIndex >= phases.size()) return "";\n        String t = phases.get(phaseIndex).say;\n        return t == null ? "" : t;\n    }\n\n    private void resetSmartReading() {\n        smartReadIndex = 0;\n        smartReadStepLength = 1;\n        smartReadStepElapsedMs = 0.0;\n        autoScrollCarry = 0.0;\n        autoPhaseReadyAt = 0L;\n        if (readProgressView != null) { readProgressView.setProgress(0f, autoScroll); readProgressView.invalidate(); }\n    }\n\n    private int readingStepLength(String text, int index) {\n        if (index < 0 || index >= text.length()) return 1;\n        if (text.startsWith("...", index)) return 3;\n        if (text.startsWith("\\n\\n", index)) return 2;\n        if (text.charAt(index) == '[') {\n            int end = text.indexOf(']', index);\n            if (end > index && end - index < 30) return end - index + 1;\n        }\n        return 1;\n    }\n\n    private double readingStepCostMs(String text, int index, int stepLength) {\n        if (index < 0 || index >= text.length()) return 30.0;\n        int wpm = readingWordsPerMinute();\n        double pauseScale = Math.max(0.68, Math.min(1.45, 90.0 / Math.max(1, wpm)));\n        if (stepLength > 1 && text.charAt(index) == '[') {\n            String cue = text.substring(index, Math.min(text.length(), index + stepLength)).toLowerCase(Locale.ROOT);\n            if (cue.contains("silence")) return 2600.0 * pauseScale;\n            if (cue.contains("vague")) return 1100.0 * pauseScale;\n            return 800.0 * pauseScale;\n        }\n        if (stepLength == 3 && text.startsWith("...", index)) return 1250.0 * pauseScale;\n        if (stepLength == 2 && text.startsWith("\\n\\n", index)) return 900.0 * pauseScale;\n        char c = text.charAt(index);\n        if (Character.isLetterOrDigit(c) || c == '\\'' || c == '’') return 60000.0 / (Math.max(1, wpm) * 5.2);\n        if (c == ',') return 470.0 * pauseScale;\n        if (c == ';' || c == ':') return 700.0 * pauseScale;\n        if (c == '.' || c == '?' || c == '!') return 980.0 * pauseScale;\n        if (c == '…') return 1300.0 * pauseScale;\n        if (c == '—' || c == '–') return 430.0 * pauseScale;\n        if (c == '\\n') return 320.0 * pauseScale;\n        if (Character.isWhitespace(c)) return 25.0;\n        return 45.0;\n    }\n\n    private void advanceSmartReading(long deltaMs) {\n        if (!autoScroll || deltaMs <= 0) return;\n        String text = currentReadingText();\n        if (text.isEmpty()) { smartReadIndex = 0; return; }\n        double budget = deltaMs;\n        while (budget > 0.0 && smartReadIndex < text.length()) {\n            smartReadStepLength = readingStepLength(text, smartReadIndex);\n            double cost = readingStepCostMs(text, smartReadIndex, smartReadStepLength);\n            double remain = Math.max(1.0, cost - smartReadStepElapsedMs);\n            if (budget >= remain) {\n                budget -= remain;\n                smartReadIndex = Math.min(text.length(), smartReadIndex + smartReadStepLength);\n                smartReadStepElapsedMs = 0.0;\n            } else {\n                smartReadStepElapsedMs += budget;\n                budget = 0.0;\n            }\n        }\n        updateSmartScroll(text);\n    }\n\n    private float currentReadingProgress(String text) {\n        if (text == null || text.isEmpty()) return 1f;\n        if (smartReadIndex >= text.length()) return 1f;\n        double cost = readingStepCostMs(text, smartReadIndex, Math.max(1, smartReadStepLength));\n        double frac = Math.max(0.0, Math.min(1.0, smartReadStepElapsedMs / Math.max(1.0, cost)));\n        double pos = smartReadIndex + Math.max(1, smartReadStepLength) * frac;\n        return (float) Math.max(0.0, Math.min(1.0, pos / text.length()));\n    }\n\n    private boolean smartReadingFinished() {\n        String text = currentReadingText();\n        return text.trim().isEmpty() || smartReadIndex >= text.length();\n    }\n\n    private void updateSmartScroll(String text) {\n        float progress = currentReadingProgress(text);\n        if (readProgressView != null) { readProgressView.setProgress(progress, autoScroll); readProgressView.invalidate(); }\n        if (textScroll == null || sayText == null || sayText.getLayout() == null || text.isEmpty()) return;\n        int offset = Math.max(0, Math.min(text.length() - 1, (int) Math.floor(progress * Math.max(0, text.length() - 1))));\n        android.text.Layout layout = sayText.getLayout();\n        int line = layout.getLineForOffset(offset);\n        int lineStart = layout.getLineStart(line);\n        int lineEnd = Math.max(lineStart + 1, layout.getLineEnd(line));\n        float lineFrac = Math.max(0f, Math.min(1f, (offset - lineStart) / (float) Math.max(1, lineEnd - lineStart)));\n        float localY = layout.getLineTop(line) + lineFrac * (layout.getLineBottom(line) - layout.getLineTop(line));\n        Rect rect = new Rect();\n        sayText.getDrawingRect(rect);\n        textScroll.offsetDescendantRectToMyCoords(sayText, rect);\n        int desired = rect.top + Math.round(localY) - Math.round(textScroll.getHeight() * 0.38f);\n        int maxScroll = Math.max(0, textScroll.getChildAt(0).getHeight() - textScroll.getHeight());\n        desired = Math.max(0, Math.min(maxScroll, desired));\n        int current = textScroll.getScrollY();\n        int diff = desired - current;\n        int next = Math.abs(diff) <= 2 ? desired : current + Math.round(diff * 0.24f);\n        textScroll.scrollTo(0, Math.max(0, Math.min(maxScroll, next)));\n    }\n\n    private void startTicker() {\n        stopTicker();\n        ticker = new Runnable() {\n            @Override public void run() {\n                if (running) {\n                    long now = SystemClock.elapsedRealtime();\n                    long d = Math.max(0L, now - lastTick);\n                    lastTick = now;\n                    globalElapsedMs += d;\n                    phaseElapsedMs += d;\n\n                    if (autoScroll && now > manualScrollUntil) advanceSmartReading(d);\n\n                    if (autoPhase && phaseIndex + 1 < phases.size()) {\n                        long planned = phases.get(phaseIndex).minutes * 60000L;\n                        boolean ready = phaseElapsedMs >= planned && smartReadingFinished();\n                        if (ready) {\n                            if (autoPhaseReadyAt == 0L) autoPhaseReadyAt = now + 2500L;\n                            else if (now >= autoPhaseReadyAt) {\n                                movePhase(1);\n                                lastTick = now;\n                            }\n                        } else autoPhaseReadyAt = 0L;\n                    } else autoPhaseReadyAt = 0L;\n                    updatePlayer();\n                }\n                handler.postDelayed(this, 40L);\n            }\n        };\n        handler.post(ticker);\n    }\n\n    private void stopTicker() {'''
